package project.init.account.domain.entity;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.FetchType;import jakarta.persistence.Id;import jakarta.persistence.IdClass;import jakarta.persistence.JoinColumn;import jakarta.persistence.ManyToOne;import jakarta.persistence.Table;import lombok.AllArgsConstructor;import lombok.Data;import lombok.Getter;import lombok.NoArgsConstructor;import lombok.Setter;import java.io.Serializable;@Entity@Getter@Setter@Table(name = "account_role")@IdClass(AccountRole.AccountRoleId.class)public class AccountRole {    @Id    @Column(name = "account_code", length = 50)    private String accountCode;    @Id    @Column(name = "role_id")    private Integer roleId;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "account_code", insertable = false, updatable = false)    private Account account;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "role_id", insertable = false, updatable = false)    private Role role;    @Data    @NoArgsConstructor    @AllArgsConstructor    public static class AccountRoleId implements Serializable {        private String accountCode;        private Integer roleId;    }}